    h, w = len(grid), len(grid[0])

    # Locate regularly spaced divider rows and columns: these are the lines
    # whose cells are mostly the same color, unlike the patterned interiors.
    row_scores = [
        max(grid[r].count(c) for c in set(grid[r]))
        for r in range(h)
    ]
    col_scores = [
        max(sum(grid[r][c] == color for r in range(h))
            for color in {grid[r][c] for r in range(h)})
        for c in range(w)
    ]

    def find_periodic(scores):
        peak = max(scores)
        candidates = [i for i, score in enumerate(scores) if score >= peak * 0.8]
        best = None
        for step in range(2, max(3, len(scores) // 2 + 1)):
            seq = [p for p in candidates if (p - candidates[0]) % step == 0]
            if len(seq) >= 2 and (best is None or len(seq) > len(best)):
                best = seq
        return best or candidates

    rs = find_periodic(row_scores)
    cs = find_periodic(col_scores)

    # Use the modal row/column spacing, retaining the regular divider locations.
    def regularize(points):
        if len(points) < 2:
            return points
        from collections import Counter
        gaps = [b-a for a, b in zip(points, points[1:])]
        step = Counter(gaps).most_common(1)[0][0]
        start = points[0]
        return list(range(start, points[-1] + 1, step))

    rs, cs = regularize(rs), regularize(cs)
    if not rs or not cs:
        return grid

    # The interior fill is the color appearing most often away from divider lines.
    line_cells = {(r, c) for r in rs for c in range(w)}
    line_cells |= {(r, c) for r in range(h) for c in cs}
    from collections import Counter
    interior = Counter(grid[r][c] for r in range(h) for c in range(w)
                       if (r, c) not in line_cells)
    fill = interior.most_common(1)[0][0] if interior else grid[0][0]

    out = []
    for r in rs[:-1]:
        row = []
        for c in cs[:-1]:
            v = grid[r][c]
            row.append(fill if v == grid[rs[0]][cs[0]] else v)
        out.append(row)
