    def find_lines(length, score):
        best = None
        for step in range(2, length):
            for start in range(min(step, length)):
                pts = list(range(start, length, step))
                if len(pts) < 2:
                    continue
                strength = sum(score(p) for p in pts)
                if best is None or strength > best[0]:
                    best = (strength, pts)
        return best[1] if best else []

    rows = find_lines(h, lambda r: sum(x == divider for x in grid[r]))
    cols = find_lines(w, lambda c: sum(grid[r][c] == divider for r in range(h)))

    if len(rows) < 2 or len(cols) < 2:
        return [[fill]]

    out = [[fill for _ in range(len(cols) - 1)] for _ in range(len(rows) - 1)]
    for i, r in enumerate(rows[:-1]):
        for j, c in enumerate(cols[:-1]):
            v = grid[r][c]
            if v != divider:
