def transform(grid):
    h, w = len(grid), len(grid[0])

    # Find the repeating lattice by choosing the row/column period and offset
    # with the strongest uniform-line evidence.
    def lattice(length, line_score):
        best = None
        for step in range(2, length):
            for offset in range(step):
                positions = list(range(offset, length, step))
                if len(positions) < 2:
                    continue
                score = sum(line_score(p) for p in positions)
                if best is None or score > best[0]:
                    best = (score, positions)
        return best[1] if best else []

    row_lines = lattice(
        h, lambda r: max(grid[r].count(v) for v in set(grid[r]))
    )
    col_lines = lattice(
        w, lambda c: max(sum(grid[r][c] == v for r in range(h))
                         for v in {grid[r][c] for r in range(h)})
    )

    if len(row_lines) < 2 or len(col_lines) < 2:
        return grid

    # The ordinary color on divider lines is replaced by the interior tile
    # color; unusual colors at line intersections are retained as markers.
    interior = [grid[r][c] for r in range(h) for c in range(w)
                if r not in row_lines and c not in col_lines]
    from collections import Counter
    fill = Counter(interior).most_common(1)[0][0]
    line_vals = [grid[r][c] for r in row_lines for c in col_lines]
    divider = Counter(line_vals).most_common(1)[0][0]

    return [
        [fill if grid[r][c] == divider else grid[r][c]
         for c in col_lines[:-1]]
        for r in row_lines[:-1]
    ]
